def missing_number(nums):
    x = len(nums)
    for i, n in enumerate(nums):
        x ^= i ^ n
    return x

def majority(nums):
    cand, count = None, 0
    for n in nums:
        if count == 0:
            cand = n
        count += 1 if n == cand else -1
    return cand

def find_duplicates(nums):
    out = []
    for n in nums:
        i = abs(n) - 1
        if nums[i] < 0:
            out.append(abs(n))
        nums[i] = -nums[i]
    return out
